# Pinned riscv-opcodes arg_lut projection.  Encoding, boundary, and supply
# owners all consume this one field-range table; keep it data-only so adding a
# form does not add another encoder branch.
def _field_ranges(data: str) -> dict[str, tuple[int, int]]:
    fields = data.split()
    return {
        name: (int(msb), int(lsb))
        for name, msb, lsb in zip(fields[::3], fields[1::3], fields[2::3])
    }


