OFFICIAL_ALL_CATALOG_BY_MNEMONIC = {
    item.mnemonic: item for item in OFFICIAL_ALL_CATALOG_FORMS
}

_SELECTED_VECTOR_MNEMONICS = frozenset((
    "vadd_vi", "vadd_vv", "vadd_vx", "vand_vv", "vcompress_vm",
    "vle8_v", "vlse32_v", "vmerge_vvm", "vmseq_vv", "vmv_v_i",
    "vredsum_vs", "vse8_v", "vsetivli", "vsetvl", "vsetvli",
    "vslideup_vx", "vsse32_v", "vsub_vv",
))
_SELECTED_NON_SCALAR_GROUPS = frozenset((
    "h", "sdext", "smrnmi", "ssctr", "svinval", "svinval_h",
    "zabhlrsc", "zbp", "zibi", "zicfiss",
))
_SELECTED_FORM_OVERRIDES = {
    "clz": (("rv_zbb",), "zbb"),
    "clzw": (("rv64_zbb",), "zbb"),
    "max": (("rv_zbb",), "zbb"),
    "maxu": (("rv_zbb",), "zbb"),
    "min": (("rv_zbb",), "zbb"),
    "minu": (("rv_zbb",), "zbb"),
    "pack": (("rv_zbkb", "rv_zk", "rv_zkn", "rv_zks"), "zbkb+zk+zkn+zks"),
    "sext_b": (("rv_zbb",), "zbb"),
    "sext_h": (("rv_zbb",), "zbb"),
    "sh1add": (("rv_zba",), "zba"),
}

OFFICIAL_SELECTED_SCALAR_FORMS = tuple(
    replace(form, source_extensions=override[0], extension_group=override[1])
    if (override := _SELECTED_FORM_OVERRIDES.get(form.mnemonic)) else form
    for form in OFFICIAL_ALL_CATALOG_FORMS
    if not (
        ((form.extension_group == "p" or form.extension_group.startswith("p+"))
         and form.mnemonic not in _SELECTED_FORM_OVERRIDES)
        or form.extension_group in _SELECTED_NON_SCALAR_GROUPS
        or form.extension_group.startswith("zv")
        or (form.extension_group == "v" and form.mnemonic not in _SELECTED_VECTOR_MNEMONICS)
    )
)

OFFICIAL_SELECTED_SCALAR_BY_MNEMONIC = {
    item.mnemonic: item for item in OFFICIAL_SELECTED_SCALAR_FORMS
}

OFFICIAL_UNRATIFIED_SOURCE_EXTENSIONS = frozenset(('rv32_p', 'rv64_p', 'rv64_zbp', 'rv_p', 'rv_zabhlrsc', 'rv_zalasr', 'rv_zbp', 'rv_zibi', 'rv_zvabd', 'rv_zvdot4a', 'rv_zvfbdota32f', 'rv_zvfofp4min', 'rv_zvfofp8min', 'rv_zvfqwbdota8f', 'rv_zvfqwdota8f', 'rv_zvfwbdota16bf', 'rv_zvfwdota16bf', 'rv_zvqwbdota8i', 'rv_zvqwdota8i', 'rv_zvzip'))
CATALOG_PARTITION_RATIFIED = "ratified"
CATALOG_PARTITION_EXPERIMENTAL_UNRATIFIED = "experimental-unratified"


def catalog_partition_for_form(form: OfficialForm) -> str:
    if any(source in OFFICIAL_UNRATIFIED_SOURCE_EXTENSIONS for source in form.source_extensions):
        return CATALOG_PARTITION_EXPERIMENTAL_UNRATIFIED
    return CATALOG_PARTITION_RATIFIED


def official_form(mnemonic: str) -> OfficialForm | None:
    return OFFICIAL_SELECTED_SCALAR_BY_MNEMONIC.get(mnemonic) or OFFICIAL_ALL_CATALOG_BY_MNEMONIC.get(mnemonic)
